.tab-btn:hover { border-color: #86868b; color: #f5f5f7; }
.tab-btn.active { background: #f5f5f7; color: #1d1d1f; border-color: #f5f5f7; }

.tab-content { display: none; }
.tab-content.active { display: flex; gap: 16px; overflow-x: auto; scrollbar-width: none; padding-bottom: 8px; }
.tab-content::-webkit-scrollbar { display: none; }

.ent-card {
  min-width: 260px;
  width: 260px;
  flex-shrink: 0;
  border-radius: 14px;
  overflow: hidden;
  background: #2d2d30;
  transition: transform var(--transition);
}
.ent-card:hover { transform: translateY(-2px); }
.ent-card .ent-img {
  width: 100%;
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
}
.ent-card .ent-body { padding: 16px; }
.ent-card .ent-body .label { font-size: 11px; color: #86868b; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 4px; }
.ent-card .ent-body h4 { font-size: 16px; font-weight: 600; color: #f5f5f7; margin-bottom: 8px; }
.ent-card .ent-body a { font-size: 14px; font-weight: 500; }

/* Brand Collab */
.brand-collab {
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  border-radius: var(--card-radius);
  padding: 60px 40px;
  margin: 40px 0;
  color: #fff;
  text-align: center;
}
.brand-collab h2 { font-size: 36px; font-weight: 700; margin-bottom: 8px; }
.brand-collab p { font-size: 18px; color: #a1a1a6; max-width: 560px; margin: 0 auto 20px; }
.brand-collab a { color: #2997ff; font-size: 16px; font-weight: 500; }

/* Quick Links */
.quick-links {
  display: flex;
  gap: 12px;
  padding: 40px 0;
  flex-wrap: wrap;
  justify-content: center;
}
.quick-link {
  padding: 12px 28px;
  border-radius: 100px;
  border: 1px solid #d2d2d7;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-primary);
  transition: all var(--transition);
}
.quick-link:hover { background: var(--color-bg-alt); text-decoration: none; }

/* Savings Grid */
.savings-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding: 24px 0 40px;
}
.savings-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 24px;
}
.savings-card h3 { font-size: 18px; font-weight: 600; margin-bottom: 8px; }
.savings-card p { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }

/* Store Hero */
.store-hero {
  text-align: center;
  padding: 60px 0 20px;
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -1px;
  margin-bottom: 8px;
}
.store-hero .subtitle {
  font-size: 22px;
  color: var(--color-secondary);
}
.store-hero .hero-links {
  display: flex;
  gap: 24px;
  justify-content: center;
  margin-top: 16px;
  flex-wrap: wrap;
}
.store-hero .hero-links a { font-size: 15px; font-weight: 500; }

/* Experience / Support Section */
.support-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  padding: 24px 0 40px;
}
.support-card {
  background: var(--color-bg-alt);
  border-radius: var(--card-radius);
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.support-card .support-icon { font-size: 32px; margin-bottom: 8px; }
.support-card h3 { font-size: 20px; font-weight: 600; }
.support-card p { font-size: 14px; color: var(--color-secondary); line-height: 1.5; }

/* Footer */
.site-footer {
  background: var(--color-bg-alt);
  border-top: 1px solid #d2d2d7;
  padding: 40px 0 24px;
  margin-top: 60px;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 24px;
  padding-bottom: 32px;
  border-bottom: 1px solid #d2d2d7;
}
.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary);
  margin-bottom: 12px;
  cursor: default;
}
.footer-col ul { list-style: none; }
.footer-col ul li { margin-bottom: 8px; }
.footer-col ul li a { font-size: 12px; color: var(--color-secondary); }
.footer-col ul li a:hover { color: var(--color-primary); }

.footer-legal {
  padding-top: 20px;
  font-size: 11px;
  color: var(--color-secondary);
  line-height: 1.6;
}
.footer-legal p { margin-bottom: 8px; }
.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 12px;
  font-size: 12px;
  color: var(--color-secondary);
}

/* Mobile footer accordion */
.footer-toggle { display: none; }

/* Promo banner within section */
.promo-banner {
  background: var(--color-bg-alt);
  border-radius: 12px;
  padding: 16px 24px;
  font-size: 14px;
  color: var(--color-secondary);
  margin-bottom: 24px;
  text-align: center;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: 1fr 1fr; }
  .savings-grid { grid-template-columns: repeat(2, 1fr); }
  .hero-tile { min-height: 380px; padding: 36px 28px; }
  .hero-tile h2 { font-size: 32px; }
  .section-heading h2 { font-size: 40px; }
}

@media (max-width: 768px) {
  .top-nav nav { display: none; }
  .top-nav nav.open { display: flex; flex-direction: column; position: absolute; top: 52px; left: 0; right: 0; background: #fff; padding: 16px 24px; border-bottom: 1px solid #e0e0e0; gap: 16px; }
  .nav-toggle { display: block; }

  .product-grid { grid-template-columns: 1fr; }
  .hero-tile { min-height: 320px; }
  .hero-tile h2 { font-size: 28px; }
  .section-heading h2 { font-size: 32px; }
  .category-hero h1 { font-size: 40px; }
  .store-hero h1 { font-size: 40px; }

  .savings-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }

  .card { min-width: 240px; width: 240px; }
  .info-card { min-width: 220px; width: 220px; }

  .footer-grid { grid-template-columns: 1fr; gap: 0; }
  .footer-col { border-bottom: 1px solid #d2d2d7; }
  .footer-col h4 {
    cursor: pointer;
    padding: 14px 0;
    margin-bottom: 0;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .footer-col h4::after { content: '+'; font-size: 18px; font-weight: 300; color: var(--color-secondary); transition: transform var(--transition); }
  .footer-col.open h4::after { content: '−'; }
  .footer-col ul { display: none; padding-bottom: 14px; }
  .footer-col.open ul { display: block; }
  .footer-toggle { display: block; }

  .footer-bottom { flex-direction: column; gap: 8px; text-align: center; }
}

@media (max-width: 480px) {
  .hero-tile { padding: 28px 20px; min-height: 280px; }
  .hero-tile h2 { font-size: 24px; }
  .tab-bar { gap: 6px; }
  .tab-btn { padding: 8px 16px; font-size: 13px; }
  .store-hero .hero-links { flex-direction: column; align-items: center; }
}

